// High-level service depends on interface only
@Service
public class UserService {
    private final UserRepository repository; // Interface type

    public UserService(UserRepository repository) { // Constructor injection
        this.repository = repository; // Spring injects JpaUserRepository
    }

    public User getUser(Long id) {
        return repository.findById(id)
            .orElseThrow(() -> new UserNotFoundException(id));
    }
}

// WRONG: DIP violation - tight coupling
@Service
public class OrderService {
    private final OrderRepository repository;

    public OrderService() {
        this.repository = new MySQLOrderRepository(); // Hard dependency
    }

    public void createOrder(String item, int quantity) {
        var order = new Order(item, quantity); // This new is fine - value object
        repository.save(order);
    }
}

// CORRECT: DIP compliant - loose coupling
@Service
public class OrderService {
    private final OrderRepository repository; // Interface type

    public OrderService(OrderRepository repository) { // Injected externally
        this.repository = repository; // Could be MySQL, Mongo, or mock
    }

    public void createOrder(String item, int quantity) {
        var order = new Order(item, quantity); // Still fine
        repository.save(order); // Calls interface method
    }
}

// Production class following DIP
@Service
public class OrderService {
    private final OrderRepository repository;

    public OrderService(OrderRepository repository) {
        this.repository = repository;
    }

    public BigDecimal calculateTotal(Long orderId) {
        var order = repository.findById(orderId)
            .orElseThrow(() -> new OrderNotFoundException(orderId));
        return order.items().stream()
            .map(item -> item.price().multiply(BigDecimal.valueOf(item.quantity())))
            .reduce(BigDecimal.ZERO, BigDecimal::add);
    }
}

// Unit test with mock
class OrderServiceTest {
    @Test
    void calculateTotal_returnsCorrectSum() {
        var mockRepository = Mockito.mock(OrderRepository.class); // Mock the interface
        var testOrder = new Order(1L, List.of(
            new OrderItem("Laptop", new BigDecimal("1000"), 2)
        ));
        Mockito.when(mockRepository.findById(1L)).thenReturn(Optional.of(testOrder));

        var service = new OrderService(mockRepository); // Inject the mock
        var total = service.calculateTotal(1L);

        assertEquals(new BigDecimal("2000"), total); // Test passes instantly
    }
}
